"""Documented conflict anchors and battle sites, never occupation polygons."""
import pathlib,json,urllib.parse
OUT=pathlib.Path(__file__).resolve().parents[1]/'public/data';features=[]
def add(name,xy,a,b,kind,countries,article,source=None,note=''):
 p=dict(uid='conflict-'+str(len(features)+1),conflictId='conflict-'+str(len(features)+1),name=name,originalName=name,start=a,end=b,kind=kind,countries=countries.split(),country='Conflicto documentado',rank=0,precision=9 if kind=='conflict-reference' else 11,source=source or 'https://en.wikipedia.org/wiki/'+urllib.parse.quote(article,safe='()_'),sourceLabel='Fuente del episodio',note=note or ('Anclaje visual regional del conflicto; no localiza cada combate ni describe un frente u ocupación.' if kind=='conflict-reference' else 'Localización aproximada del episodio; el punto no representa el perímetro de la batalla ni la posición de cada ejército.'),uncertaintyKm=5)
 features.append(dict(type='Feature',id=p['uid'],geometry=dict(type='Point',coordinates=xy),properties=p))
def region(name,xy,a,b,countries,article,source=None):add(name,xy,f'{a}-01-01',f'{b}-12-31','conflict-reference',countries,article,source)
def battle(name,xy,a,b,countries,article,source=None):add(name,xy,a,b,'battle',countries,article,source)
